import { HttpClient } from '@angular/common/http';
import { Component, inject, OnInit } from '@angular/core';
import { ActivatedRoute, RouterModule } from '@angular/router';
import { environment } from '../../../../environments/environment';
import { TimeAgoPipe } from "../../../common/time-ago.pipe";
import { CommonModule } from '@angular/common';
import { ToastService } from '../../../common/toast.service';
import { AuthService } from '../../../services/auth.service';
import { FormsModule } from '@angular/forms';
import { UserService } from '../../../services/user.service';

@Component({
  selector: 'app-post',
  standalone: true,
  imports: [TimeAgoPipe, RouterModule, CommonModule, FormsModule],
  templateUrl: './post.component.html',
  styleUrl: './post.component.scss'
})
export class PostComponent implements OnInit {
  auth = inject(AuthService);
  postId!: string;
  postData: any = null;
  animate = false;
  newComment = '';
  editingCommentId: number | null = null;
  editCommentText: string = '';
  comments: any[] = [];
  showComments: boolean = true;
  s3Url = environment.s3Url;
  whoamiId: any = null; // to store current user ID
  constructor(private route: ActivatedRoute, private http: HttpClient, private toastService: ToastService, private userService: UserService) { }

  ngOnInit(): void {
    this.route.queryParams.subscribe(params => {
      this.postId = params['id'];  // 👈 Get post id from query
      if (this.postId) {
        this.auth.checkAuth();
        this.singleposts(+this.postId);
        this.userService.getUser().subscribe((user) => {
          if (user) {
            this.whoamiId = user?.id;
          } 
        });

      }
    });
  }
  toggleComments() {
  this.showComments = !this.showComments;
}
  singleposts(id: number) {
    let URL;
    if (this.auth.isLoggedIn() === true) {
      URL = `${environment.apiUrl}/communities/users?populate=communityComments&id=${id}`
    }
    else {
      URL = `${environment.apiUrl}/communities?populate=postTag&populate=createdBy&id=${id}`
    }
    this.http.get<any>(URL)
      .subscribe({
        next: (res) => {
          this.postData = res.data.data[0];
          this.comments = this.postData?.communityComments?.slice().reverse();

        },
        error: (err) => {
          console.error('Error fetching Events:', err);
        }
      });
  }
  copyPostLink(postId: string) {
    const url = `${window.location.origin}/homepage/post?id=${postId}`;

    navigator.clipboard.writeText(url).then(() => {
      this.toastService.showToast('Link copied to clipboard ✅', 'success');
    }).catch(err => {
      console.error('Failed to copy link: ', err);
    });
  }

  toggleLike(post: any) {
    if (!post) return;
    const token = localStorage.getItem('authToken');
    if (!token) {
      this.toastService.showToast('Please login to like the posts.', 'success');
      return; // stop here
    }

    // trigger animation
    post.animate = true;

    // optimistic UI update
    const prevLiked = post.isLiked;
    post.isLiked = !prevLiked;
    post.likes += post.isLiked ? 1 : -1;

    // call API
    this.http.post<any>(`${environment.apiUrl}/communities/likes`, { communityId: post.id })
      .subscribe({
        next: (res) => {
         
        },
        error: (err) => {
          console.error("Error in Like post:", err);
          // revert if failed
          post.isLiked = prevLiked;
          post.likes += post.isLiked ? 1 : -1;
        }
      });

    // reset animate flag after animation
    setTimeout(() => { post.animate = false; }, 300);
  }

  addComment() {
    if (this.newComment.trim()) {
      const payload = {
        caption: this.newComment,
        communityId: +this.postId
      }

      this.http.post<any>(`${environment.apiUrl}/communities/comment`, payload)
        .subscribe({
          next: (res) => {
            this.singleposts(+this.postId);
            this.newComment = '';
            this.toastService.showToast('Comment Added', 'success');
          },
          error: (err) => {
            console.error("Error in Comment:", err);
            this.toastService.showToast('Comment Failed', 'danger');
          }
        });
    }
  }
  startEdit(comment: any) {
    this.editingCommentId = comment.id;
    this.editCommentText = comment.caption; // bind to input
  }

  cancelEdit() {
    this.editingCommentId = null;
    this.editCommentText = '';
  }
  updateComment(commentId: number) {
    const payload = { caption: this.editCommentText ,
      commentId: commentId
    };
    this.http.put(`${environment.apiUrl}/communities/comment`, payload)
      .subscribe({
        next: () => {
          this.singleposts(+this.postId); // refresh comments
          this.editingCommentId = null;
          this.editCommentText = '';
          this.toastService.showToast('Comment Updated', 'success');
        },
        error: (err) => {
          console.error("Error updating comment:", err);
          this.toastService.showToast('Update Failed', 'danger');
        }
      });
  }
  deleteComment(commentId: number) {
    if (!confirm('Are you sure you want to delete this comment?')) return;

    this.http.delete<any>(`${environment.apiUrl}/communities/comment/${commentId}`)
      .subscribe({
        next: (res) => {
          this.singleposts(+this.postId); // refresh comments
          this.toastService.showToast('Comment Deleted', 'success');
        },
        error: (err) => {
          console.error("Error deleting comment:", err);
          this.toastService.showToast('Delete Failed', 'danger');
        }
      });
  }

}
